export default function Wave1StateHub() {
  const params = useParams();
  const serviceSlug = params.service as string;
  const stateSlug = params.state as string;
  const hub = STATE_HUBS[`${serviceSlug}/${stateSlug}`];
  if (!hub) {
    return (<div className="min-h-screen flex items-center justify-center"><p>Page not found.</p></div>);
  }
  return (
    <div className="min-h-screen bg-white">
      <main className="max-w-4xl mx-auto px-4 py-12">
        <nav className="text-sm text-gray-500 mb-6">
          <a href="/" className="hover:underline">Home</a>{" > "}
          <a href="/wave1/" className="hover:underline">Services by Location</a>{" > "}
          <a href={`/wave1/${serviceSlug}/`} className="hover:underline">{hub.title}</a>{" > "}
          <span>{hub.state}</span>
        </nav>
        <h1 className="text-4xl font-bold mb-6">{hub.title} in {hub.state}</h1>
        <p className="text-lg text-gray-700 mb-8">
          Licensed {hub.title.toLowerCase()} engineers serving {hub.state} metros. 
          Select your city for local permitting notes, code requirements, and 24-hour quotes.
        </p>
        <div className="grid md:grid-cols-3 gap-4">
          {hub.cities.map((c) => (
            <Link key={c.city_slug} href={`/wave1/${serviceSlug}/${c.city_slug}/${stateSlug}/`}>
              <a className="block border rounded-lg p-4 hover:shadow-lg transition-shadow">
                <h2 className="text-xl font-semibold">{c.city}</h2>
                <p className="text-sm text-gray-500">{c.metro} metro</p>
              </a>
            </Link>
          ))}
        </div>
      </main>
    </div>
  );
}